export const ResidueClassSchema = z.enum(RESIDUE_CLASSES);

/**
 * What a residue entry cost the run, counted. Prose records THAT evidence was dropped;
 * this records HOW MUCH and of which dimension, so "what did the cap cost us" is answered
 * across runs from the ledger (`src/bench/metrics.ts`) instead of by reading paragraphs.
 */
export const DroppedEvidenceSchema = z
  .strictObject({
    total: z.number().int().min(0),
    byDimension: z.record(z.string().min(1), z.number().int().min(0)),
  })
  .readonly();

export const ResidueEntrySchema = z
  .strictObject({
    class: ResidueClassSchema,
    anchor: FindingAnchorSchema,
    findingIds: z.array(z.string().min(1)).readonly(),
    text: z.string().min(1),
    /** Present on an entry that stands for discarded evidence; absent means nothing was counted. */
    dropped: DroppedEvidenceSchema.optional(),
  })
  .readonly();

/** The residue document a run writes: the versioned envelope around its entries. */
export const ResidueDocSchema = z.strictObject({
  schemaVersion: SchemaVersionSchema,
  entries: z.array(ResidueEntrySchema).readonly(),
});

export type ResidueClass = z.infer<typeof ResidueClassSchema>;
export type DroppedEvidence = Readonly<z.infer<typeof DroppedEvidenceSchema>>;
export type ResidueEntry = Readonly<z.infer<typeof ResidueEntrySchema>>;

